534	/// Gets all the short options, their visible aliases and flags of a [`clap::Command`].
535	/// Includes `h` and `V` depending on the [`clap::Command`] settings.
536	fn shorts_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
537	    debug!("shorts: name={}", p.get_name());
538	
539	    p.get_arguments()
540	        .filter_map(|a| {
541	            a.get_short_and_visible_aliases().map(|shorts| {
542	                shorts.into_iter().map(|s| {
543	                    populate_arg_candidate(CompletionCandidate::new(s.to_string()), a).help(
544	                        a.get_help()
545	                            .cloned()
546	                            .or_else(|| a.get_long().map(|long| format!("--{long}").into())),
547	                    )
548	                })
549	            })
550	        })
551	        .flatten()
552	        .collect()
553	}
554	
555	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
556	    candidate
557	        .help(arg.get_help().cloned())
558	        .id(Some(format!("arg::{}", arg.get_id())))
559	        .tag(Some(
560	            arg.get_help_heading()
561	                .unwrap_or("Options")
562	                .to_owned()
563	                .into(),
564	        ))
565	        .display_order(Some(arg.get_display_order()))
566	        .hide(arg.is_hide_set())
567	}
