580	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
581	///
582	/// Subcommand `rustup toolchain install` would be converted to
583	/// `("install", "rustup toolchain install")`.
584	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
585	    debug!("subcommands: name={}", p.get_name());
586	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
587	    p.get_subcommands()
588	        .flat_map(|sc| {
589	            sc.get_name_and_visible_aliases()
590	                .into_iter()
591	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
592	                .chain(sc.get_aliases().map(|s| {
593	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
594	                        .hide(true)
595	                }))
596	        })
597	        .collect()
598	}
599	
600	fn populate_command_candidate(
601	    candidate: CompletionCandidate,
602	    cmd: &clap::Command,
603	    subcommand: &clap::Command,
604	) -> CompletionCandidate {
605	    candidate
606	        .help(subcommand.get_about().cloned())
607	        .id(Some(format!("command::{}", subcommand.get_name())))
608	        .tag(Some(
609	            cmd.get_subcommand_help_heading()
610	                .unwrap_or("Commands")
611	                .to_owned()
612	                .into(),
613	        ))
614	        .display_order(Some(subcommand.get_display_order()))
615	        .hide(subcommand.is_hide_set())
616	}
617	
618	/// Parse the short flags and find the first `takes_values` option.
619	fn parse_shortflags<'c, 's>(
620	    cmd: &'c clap::Command,
621	    mut short: clap_lex::ShortFlags<'s>,
622	) -> (String, Option<&'c clap::Arg>, clap_lex::ShortFlags<'s>) {
623	    let takes_value_opt;
624	    let mut leading_flags = String::new();
625	    // Find the first takes_values option.
626	    loop {
627	        match short.next_flag() {
628	            Some(Ok(opt)) => {
629	                leading_flags.push(opt);
630	                let opt = cmd.get_arguments().find(|a| {
631	                    let shorts = a.get_short_and_visible_aliases();
632	                    let is_find = shorts.map(|v| {
633	                        let mut iter = v.into_iter();
634	                        let c = iter.find(|c| *c == opt);
635	                        c.is_some()
636	                    });
637	                    is_find.unwrap_or(false)
638	                });
639	                if opt
640	                    .map(|o| o.get_num_args().expect("built").takes_values())
641	                    .unwrap_or(false)
642	                {
643	                    takes_value_opt = opt;
644	                    break;
645	                }
646	            }
647	            Some(Err(_)) | None => {
648	                takes_value_opt = None;
649	                break;
650	            }
651	        }
652	    }
653	
654	    (leading_flags, takes_value_opt, short)
655	}
656	
657	/// Parse the positional arguments. Return the new state and the new positional index.
658	fn parse_positional<'a>(
659	    cmd: &clap::Command,
660	    pos_index: usize,
661	    is_escaped: bool,
662	    state: ParseState<'a>,
663	) -> (ParseState<'a>, usize) {
664	    let pos_arg = cmd
665	        .get_positionals()
666	        .find(|p| p.get_index() == Some(pos_index));
667	    let num_args = pos_arg
668	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
669	        .unwrap_or(1);
670	
671	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
672	        if num_args > 1 {
673	            (ParseState::Pos((pos_index, 1)), pos_index)
674	        } else {
675	            if is_escaped {
676	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
677	            } else {
678	                (ParseState::ValueDone, pos_index + 1)
679	            }
680	        }
681	    };
682	    match state {
683	        ParseState::ValueDone => {
684	            update_state_with_new_positional(pos_index)
685	        },
686	        ParseState::Pos((prev_pos_index, num_arg)) => {
687	            if prev_pos_index == pos_index {
688	                if num_arg + 1 < num_args {
689	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
690	                } else {
691	                    if is_escaped {
692	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
693	                    } else {
694	                        (ParseState::ValueDone, pos_index + 1)
695	                    }
696	                }
697	            } else {
698	                update_state_with_new_positional(pos_index)
699	            }
700	        }
701	        ParseState::Opt(..) => unreachable!(
702	            "This branch won't be hit,
703	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
704	        ),
705	    }
706	}
707	
708	/// Parse optional flag argument. Return new state
709	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
710	    let range = opt.get_num_args().expect("built");
711	    let max = range.max_values();
712	    if count < max {
713	        ParseState::Opt((opt, count + 1))
714	    } else {
715	        ParseState::ValueDone
716	    }
717	}
718	
719	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
720	    cmd.get_positionals()
721	        .find(|a| a.get_index() == Some(pos_index))
722	        .map(|p| p.is_allow_hyphen_values_set())
723	        .unwrap_or(false)
724	}
725	
726	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
727	    let val = arg.to_value_os();
728	    if val.starts_with("-") {
729	        if let ParseState::Opt((opt, _)) = state {
730	            return opt.is_allow_hyphen_values_set();
731	        }
732	    }
733	
734	    false
735	}
